/** Module key (`std:NAME`) → that std module's source. */
export const STD_SOURCES: Record<string, string> = {
  "std:array": "// `std:array` — pure-VL array/list helpers over the intrinsic floor (the emitter\n// provides the list primitives `.push` / `.length` / indexing / `map` / `filter`;\n// these derived methods are written in VL on top of them, the array dual of\n// `std:fmt`). Each takes a `self` first parameter, so it reads as a UFCS method on\n// the receiver (`xs.indexOf(3)`, `xs.includes(3)`). All are GENERIC in the element\n// type `T`, so one definition serves `i32[]`, `string[]`, … — `==` resolves per\n// element type.\n//\n// The first group is the SEARCH family (each returns an i32 / boolean, building no\n// new collection); the second is the BUILDING family (`reverse` / `concat` /\n// `mapIndexed`, each returning a NEW list). The building family is GENERIC over the\n// element type too: a generic `const out: T[] = []` followed by `out.push(…)` now\n// propagates `T` through monomorphization, so one definition builds the right list\n// per instantiation. (`slice` and the bare `map`/`filter` are emitter primitives;\n// these add what the floor does not cover.)\n\n// The index of the FIRST element equal to `needle`, or -1 if absent. `==` is the\n// element type's equality (value for scalars / strings, reference for functions).\nexport function indexOf<T>(self: T[], needle: T): i32 {\n  let i = 0\n  while i < self.length {\n    if self[i] == needle { return i }\n    i = i + 1\n  }\n  return -1\n}\n\n// The index of the LAST element equal to `needle`, or -1 if absent.\nexport function lastIndexOf<T>(self: T[], needle: T): i32 {\n  let i = self.length - 1\n  while i >= 0 {\n    if self[i] == needle { return i }\n    i = i - 1\n  }\n  return -1\n}\n\n// Whether any element equals `needle`.\nexport function includes<T>(self: T[], needle: T): boolean {\n  let i = 0\n  while i < self.length {\n    if self[i] == needle { return true }\n    i = i + 1\n  }\n  return false\n}\n\n// How many elements equal `needle`.\nexport function count<T>(self: T[], needle: T): i32 {\n  let c = 0\n  let i = 0\n  while i < self.length {\n    if self[i] == needle { c = c + 1 }\n    i = i + 1\n  }\n  return c\n}\n\n// Left fold: thread `acc` (seeded with `init`) through `f(acc, element)` for each\n// element in order, returning the final accumulator. The accumulator type `A` may\n// differ from the element type `T` (summing an `i32[]` to an `i32`, joining a\n// `string[]` to a `string`, summing an `f64[]` to an `f64`). The generic closure\n// parameter `f: (A, T) => A` is monomorphized per call shape.\nexport function reduce<T, A>(self: T[], f: (A, T) => A, init: A): A {\n  let acc = init\n  let i = 0\n  while i < self.length {\n    acc = f(acc, self[i])\n    i = i + 1\n  }\n  return acc\n}\n\n// ── The BUILDING family — each returns a NEW list, leaving its inputs unmutated. ──\n\n// `self`'s elements in reverse order.\nexport function reverse<T>(self: T[]): T[] {\n  const out: T[] = []\n  let i = self.length - 1\n  while i >= 0 {\n    out.push(self[i])\n    i = i - 1\n  }\n  return out\n}\n\n// `self` followed by `other`. The element type `T` must match (`==`-comparable not\n// required — this only moves elements), so a mixed-type concat does not type-check.\nexport function concat<T>(self: T[], other: T[]): T[] {\n  const out: T[] = []\n  let i = 0\n  while i < self.length {\n    out.push(self[i])\n    i = i + 1\n  }\n  let j = 0\n  while j < other.length {\n    out.push(other[j])\n    j = j + 1\n  }\n  return out\n}\n\n// `map` with the element INDEX: `f(element, i)` for each element, collected in\n// order into a new list. The result element type `U` may differ from `T`. The\n// emitter's bare `.map` passes only the element; this is the indexed companion.\nexport function mapIndexed<T, U>(self: T[], f: (T, i32) => U): U[] {\n  const out: U[] = []\n  let i = 0\n  while i < self.length {\n    out.push(f(self[i], i))\n    i = i + 1\n  }\n  return out\n}\n",
  "std:buffer": "// `std:buffer` — the linear-memory tier's allocator and access surface, in pure\n// VL over the `__load_*__` / `__store_*__` / `__memory_*__` intrinsic floor\n// (`docs/internals/buffer-design.md` §C, sequencing item S5). The compiler owns\n// exactly what an INSTRUCTION is; allocation POLICY is ordinary code and lives\n// here (O1 = (c): `Buffer` is std VL, not a compiler-known type).\n//\n// TWO HEAPS. A `Buf` VALUE is an ordinary WasmGC struct with ordinary VL value\n// semantics; a `Buf`'s CONTENTS live in linear memory, which the host can read\n// directly through the module's exported `memory`. `.length` is a plain field\n// read — no call, no side table.\n//\n// BOUNDS: there are none here, by design (§A4). An access past the end of the\n// memory traps in the ENGINE — that trap is the memory-safety proof, and adding\n// a VL-level check would only make it quieter. An access past the end of a\n// `Buf` but still inside the memory is NOT caught: `Buf` describes an extent,\n// it does not fence it.\n//\n// HOST CONTRACT (O5 = lazy growth, no epoch export). `Buffer(n)` grows the\n// memory when it must, and a `memory.grow` DETACHES every host view of\n// `exports.memory.buffer`. A host must therefore re-take its typed-array views\n// after any guest call that may allocate; a stale view is detectable by\n// `view.byteLength === 0` (a detached view yields `undefined` on an indexed\n// read rather than throwing). This is what Emscripten's `updateMemoryViews()`,\n// wasm-bindgen's `byteLength === 0` probe and Go's `wasm_exec.js` buffer-\n// identity check all do; none of them exports a growth counter, and neither\n// does this module.\n//\n// RECLAMATION IS MARK/RELEASE, AND IT CAN DANGLE (O6). There is no per-object\n// `free`; `bufferMark()` / `bufferRelease(mark)` move the one bump pointer, so\n// reclamation is LIFO and costs nothing. The hazard is stated here rather than\n// in a footnote because it is the FIRST way a VL program can hold a dangling\n// reference at all: a `Buf` held across a `bufferRelease` that undoes its\n// allocation still points at live, in-bounds, since-reused linear memory. Reads\n// through it return another buffer's bytes and writes through it corrupt them —\n// SILENTLY. No trap fires, because nothing is out of bounds. Treat a released\n// mark as invalidating every `Buf` allocated after it.\n//\n// PERFORMANCE. Every access below is a real wasm `call`; `wasm-opt -O` (what\n// `vl build -O` runs) does NOT inline these wrappers, `-O3 --closed-world`\n// does (§O1). Every body is now ONE instruction plus its address arithmetic —\n// `store8`/`store16` were read-modify-write emulations and `fill`/`copyFrom`\n// were byte loops until the narrow-store and bulk intrinsics landed, and the\n// swap changed no signature and no expectation.\n\n// A `Buf` is a linear-memory extent: the byte address of its first byte, and\n// the number of bytes the caller ASKED for (the allocator may reserve a few\n// more for alignment; those are invisible here).\nexport type Buf = { base: i32, length: i32 }\n\n// A wasm page is 64 KiB; `__memory_size__` / `__memory_grow__` count pages.\nconst PAGE_SHIFT = 16\nconst PAGE_MASK = 65535\n\n// POLICY 1 — the reserved low region. Byte addresses below `HEAP_BASE` are\n// never handed out. Three reasons, none of them cosmetic:\n//   - address 0 stays outside every allocation, so `base == 0` cannot be a\n//     legitimate `Buf` and a zeroed/garbage descriptor is distinguishable;\n//   - a program may still poke raw addresses through the bare intrinsics\n//     (that is the §A3 \"two users collide\" hazard), and this leaves it a\n//     documented kilobyte that `std:buffer` promises never to touch;\n//   - the host's staging ABI probe (`ioMem`, `scripts/vl-host/src/main.rs`)\n//     wants a fixed low window it can own later without moving the heap.\n// 1 KiB, not one page: reserving a whole page would force a `memory.grow`\n// during init for programs that fit comfortably in the default one.\nconst HEAP_BASE = 1024\n\n// POLICY 2 — alignment. Every allocation's SIZE is rounded up to 8 bytes, and\n// `HEAP_BASE` is a multiple of 8, so every `Buf` starts 8-byte aligned and each\n// width's natural alignment is satisfied at offset 0 and at every 8-multiple\n// offset. This is a PERFORMANCE choice, not a correctness one — wasm's\n// alignment immediate is a hint and every load/store here is legal at any\n// address (pinned by the unaligned cases in `tests/cases/memory/`). 8 is the\n// widest scalar VL can store (i64 / f64).\nconst ALIGN = 8\n\n// The bump pointer: the address one past the last byte handed out. Module-level\n// mutable state, which is exactly what makes the allocator's policy ordinary\n// VL code (§C4).\nlet bumpPtr = HEAP_BASE\n\n// `n` rounded up to the next multiple of `ALIGN`.\nfunction alignUp(n: i32): i32 {\n  const slack = n & (ALIGN - 1)\n  if slack == 0 { return n }\n  return n + (ALIGN - slack)\n}\n\n// Grow the memory until byte `end` (exclusive) is addressable. Page arithmetic\n// throughout — computing `pages * 65536` would itself overflow i32 at 2 GiB,\n// which is inside the range this can be asked about.\nfunction ensureCapacity(end: i32) {\n  let needPages = end >> PAGE_SHIFT\n  if (end & PAGE_MASK) != 0 { needPages = needPages + 1 }\n  const havePages = __memory_size__()\n  if needPages > havePages {\n    // `memory.grow` answers with the size BEFORE the growth, or -1 on failure.\n    // A refused allocation cannot be papered over — the caller is about to write\n    // through a `Buf` that has no memory behind it.\n    //\n    // MEASURED, this branch is defensive rather than routine: `Buffer`'s i32\n    // overflow guard caps `end` at 2^31, i.e. at most 32768 pages, and wasm32's\n    // own ceiling is 65536 — so the SPEC limit is unreachable from here and only\n    // host resource exhaustion can produce the -1. Both hosts grow a 2 GiB\n    // request without complaint (wasmtime 47 and V8 alike, measured), which is\n    // why no corpus fixture pins this line: there is no request that fails\n    // deterministically on every host.\n    if __memory_grow__(needPages - havePages) < 0 { __trap__() }\n  }\n}\n\n// `Buffer(n)` — reserve `n` zero-filled bytes and describe them.\n//\n// ZERO-FILL: a wasm memory starts zeroed and freshly grown pages are zeroed, so\n// bytes that have never been handed out before are zero for free — no fill loop\n// runs here. That guarantee ends at the first `bufferRelease`: addresses handed\n// out a SECOND time carry whatever the previous owner wrote. Call\n// `buf.fill(0, buf.length, 0)` when reusing a released region and zeros matter.\n//\n// Traps on a negative length and on an allocation that would carry the bump\n// pointer past 2 GiB (where an i32 byte address stops being orderable), because\n// either would silently corrupt every later allocation.\nexport function Buffer(byteLength: i32): Buf {\n  if byteLength < 0 { __trap__() }\n  const base = bumpPtr\n  const next = base + alignUp(byteLength)\n  if next < base { __trap__() }\n  ensureCapacity(next)\n  bumpPtr = next\n  return { base: base, length: byteLength }\n}\n\n// `bufferMark()` — the current bump pointer, to hand back to `bufferRelease`.\nexport function bufferMark(): i32 { return bumpPtr }\n\n// `bufferRelease(mark)` — reclaim everything allocated since `mark` in one\n// move. LIFO, no free list, no fragmentation, and NO liveness check: see this\n// module's header for the dangling-`Buf` hazard this opens, which is silent\n// corruption rather than a trap.\n//\n// Traps on a mark outside `[HEAP_BASE, bumpPtr]` — below the base it would let\n// allocations walk into the reserved region, above the pointer it re-reserves\n// bytes that are already free. Both are bugs at the call site, not recoverable\n// states.\nexport function bufferRelease(mark: i32) {\n  if mark < HEAP_BASE { __trap__() }\n  if mark > bumpPtr { __trap__() }\n  bumpPtr = mark\n}\n\n// ── Loads: eight widths, four of them signed/unsigned pairs. ──\n//\n// The signed/unsigned split is REAL here and is kept: `i32.load8_s` and\n// `i32.load8_u` are two different instructions, and of the byte 0xFF the first\n// answers -1 while the second answers 255. (The stores below have no such\n// split — see `store8`.)\n\n// The byte at `off`, sign-extended into an i32 (0xFF → -1).\nexport function loadI8(self: Buf, off: i32): i32 {\n  return __load_i8__(self.base + off)\n}\n\n// The byte at `off`, zero-extended into an i32 (0xFF → 255).\nexport function loadU8(self: Buf, off: i32): i32 {\n  return __load_u8__(self.base + off)\n}\n\n// The 16-bit halfword at `off`, sign-extended (0xFFFF → -1).\nexport function loadI16(self: Buf, off: i32): i32 {\n  return __load_i16__(self.base + off)\n}\n\n// The 16-bit halfword at `off`, zero-extended (0xFFFF → 65535).\nexport function loadU16(self: Buf, off: i32): i32 {\n  return __load_u16__(self.base + off)\n}\n\n// The 32-bit word at `off`.\nexport function loadI32(self: Buf, off: i32): i32 {\n  return __load_i32__(self.base + off)\n}\n\n// The 64-bit word at `off`.\nexport function loadI64(self: Buf, off: i32): i64 {\n  return __load_i64__(self.base + off)\n}\n\n// The 32-bit float at `off`.\nexport function loadF32(self: Buf, off: i32): f32 {\n  return __load_f32__(self.base + off)\n}\n\n// The 64-bit float at `off`.\nexport function loadF64(self: Buf, off: i32): f64 {\n  return __load_f64__(self.base + off)\n}\n\n// ── Stores: six widths, and no signed/unsigned split (O2). ──\n//\n// A store is sign-AGNOSTIC. There is exactly one instruction per width and it\n// TRUNCATES — `i32.store8` cannot tell a signed byte from an unsigned one — so\n// naming these `storeU8`/`storeI8` would falsely imply a signed twin exists.\n// Hence `store8` / `store16` against the loads' `loadI8` / `loadU8`: the\n// asymmetry is the instruction set's, and it is deliberate.\n\n// The 32-bit word at `off`.\nexport function storeI32(self: Buf, off: i32, v: i32) {\n  __store_i32__(self.base + off, v)\n}\n\n// The 64-bit word at `off`.\nexport function storeI64(self: Buf, off: i32, v: i64) {\n  __store_i64__(self.base + off, v)\n}\n\n// The 32-bit float at `off`.\nexport function storeF32(self: Buf, off: i32, v: f32) {\n  __store_f32__(self.base + off, v)\n}\n\n// The 64-bit float at `off`.\nexport function storeF64(self: Buf, off: i32, v: f64) {\n  __store_f64__(self.base + off, v)\n}\n\n// The low 8 bits of `v` at `off`. Higher bits are discarded, exactly as\n// `i32.store8` discards them — because this IS `i32.store8` (0x3a).\n//\n// This body used to be a READ-MODIFY-WRITE over the containing 32-bit word, and\n// its whole expectation set survived the swap unchanged, which is the evidence\n// that the emulation was faithful. What the emulation could not preserve was the\n// access WIDTH — it touched 4 bytes where the instruction touches 1 — and that\n// difference was unobservable from VL (no threads, no shared memory) but NOT\n// from the host: `tests/vl_exported_memory_test.ts` reads the untouched\n// neighbours through the exported memory, which is the assertion the emulation\n// would have failed.\nexport function store8(self: Buf, off: i32, v: i32) {\n  __store_i8__(self.base + off, v)\n}\n\n// The low 16 bits of `v` at `off`, little-endian — `i32.store16` (0x3b).\n//\n// This was two byte-wide read-modify-writes rather than one word-level one,\n// because a halfword at an address congruent to 3 mod 4 STRADDLES two words. The\n// instruction has no such difficulty: wasm's alignment immediate is a hint, and\n// a 16-bit store is legal and correct at every address, straddle included.\nexport function store16(self: Buf, off: i32, v: i32) {\n  __store_i16__(self.base + off, v)\n}\n\n// ── Bulk ops: one instruction each. ──\n//\n// THE ONE PLACE THIS MODULE DOES NOT PASS ITS ARGUMENT STRAIGHT THROUGH. Both\n// instructions take an UNSIGNED byte count, and VL has no unsigned i32, so a\n// negative `len` is ~4 GiB and traps in the engine. The byte loops these bodies\n// replaced treated a non-positive `len` as \"write nothing\", and that behaviour\n// is pinned (`tests/cases/std/buffer-bulk.vl`), so the guard stays. Which is the\n// right layering anyway: the intrinsic IS the instruction (`__memory_fill__`\n// traps on -5, pinned by `tests/cases/memory/bulk-negative-length-traps.vl`),\n// and softening it is POLICY, which is std's job (O1 = (c)).\n//\n// Nothing else is guarded. There is still no per-access bounds check — a range\n// that leaves the memory traps in the engine, and a range that leaves the `Buf`\n// but stays inside the memory is not caught, exactly as for every load and store\n// above. `Buf` describes an extent; it does not fence it.\n\n// Set `len` bytes starting at `off` to the low 8 bits of `byte` — `memory.fill`\n// (0xfc 11). A non-positive `len` writes nothing.\n// (Spelled as a positive `if` rather than an early `return`: a BARE `return` in a\n// void function type-checks and then fails at emit — `emitProgram: bare return is\n// not supported`. Worth knowing before reaching for a guard clause here.)\nexport function fill(self: Buf, off: i32, len: i32, byte: i32) {\n  if len > 0 { __memory_fill__(self.base + off, byte, len) }\n}\n\n// Copy `len` bytes from `src` at `srcOff` into `self` at `dstOff` — the\n// DESTINATION is the receiver (O3), matching `dst.fill(...)` and the\n// self-first UFCS shape `std:array` / `std:fmt` already establish. (`Buffer.copy`\n// is not spellable: VL has no static methods.)\n//\n// OVERLAP IS HANDLED, and it is now handled by the INSTRUCTION. `memory.copy`\n// (0xfc 10) is defined to behave as if the bytes went through a temporary —\n// memmove semantics, not memcpy — so an overlapping copy never reads a byte it\n// has already overwritten, in either direction. `self` and `src` may be the same\n// `Buf`, and may overlap partially either way.\n//\n// This body used to CHOOSE its loop direction from the absolute addresses,\n// because a naive forward loop is wrong exactly when the destination is above\n// the source. That choice is gone, not merely optimized: both directions were\n// pinned by value in `buffer-bulk.vl` before the swap and both still pass, which\n// is what makes \"the instruction has the semantics the loop was imitating\" a\n// measurement rather than a claim about the spec.\nexport function copyFrom(\n  self: Buf,\n  dstOff: i32,\n  src: Buf,\n  srcOff: i32,\n  len: i32,\n) {\n  if len > 0 { __memory_copy__(self.base + dstOff, src.base + srcOff, len) }\n}\n\n// ── Typed views (webcraft P1.1) ──────────────────────────────────────────────\n//\n// A VIEW is a `Buf` sub-range re-described in ELEMENTS rather than bytes: a byte\n// address plus an element COUNT, with an element width baked into the type. The\n// kernel it exists for is structure-of-arrays — `for i { x[i] += vx[i] }` over\n// columns — where the alternative is `loadF32(base + (i << 2))` spelled by hand\n// at every access, which is the DataView experience webcraft already has and\n// wants absorbed.\n//\n// WHY THE TWO VIEWS ARE `new` (webcraft P1.5, `docs/internals/newtype-design.md`).\n// VL is STRUCTURALLY typed: a plain `type X = {…}` names a shape, not an identity,\n// so two declarations with the same field names and types ARE THE SAME TYPE and\n// are silently interchangeable. Spelled plainly — both views as\n// `{ base: i32, length: i32 }` — an `I32View` satisfies every `F32View` parameter\n// in this module and `iv.getF32(0)` type-checks while REINTERPRETING four integer\n// bytes as a float, with no diagnostic. Measured, not feared.\n//\n// `new` mints the identity the shape does not: the two declarations are now\n// distinct to the checker even though the shape is identical, and the mismatch is\n// a named reject (`tests/cases/std/buffer-view-element-type-mismatch.vl`). It is\n// ZERO-COST — a newtype is erased before the emitter runs, so the two views still\n// share one wasm heap type and the module is byte-identical to the one this\n// section shipped with `f32base`/`i32base` field names.\n//\n// THE ELEMENT WIDTH IS IN THE TYPE, NOT IN A FIELD NAME. That is the whole point:\n// every further width this family grows (i64, f64, the narrow widths) is one more\n// `new`, not one more name hack.\n//\n// `.length` is the ELEMENT count, per the P1.1 spec's `x.length`. It is a plain\n// struct field — no call, no side table, exactly as `Buf.length` is.\n//\n// BOUNDS ARE CHECKED HERE, AND THIS IS THE ONE PLACE IN `std:buffer` THAT\n// CHECKS. Everything above obeys §A4 (the engine traps; a `Buf` describes an\n// extent and does not fence it). A view is different, and deliberately so,\n// because the P1.1 spec asks for it in the same breath as the surface:\n// \"index-bounds = count\". The reason the answer differs is that the FAILURE\n// MODE differs. An out-of-range byte offset on a `Buf` is usually far out and\n// leaves the memory, so the engine catches it. An out-of-range ELEMENT index on\n// a view is usually one or two past the end of a column — still inside the\n// memory, still inside some other column — so the engine sees nothing wrong and\n// the read returns A NEIGHBOUR'S BYTES. That is a silent wrong answer in exactly\n// the code (SoA kernels, snapshot/rollback, the differential harness) whose\n// entire value is being byte-comparable with a TS twin. So each accessor traps\n// on an index outside `[0, length)` via `__trap__` (`unreachable`) — the same\n// loud, deterministic, unrecoverable stop the engine's own bounds trap is.\n//\n// THE CHECK IS TWO COMPARES PER ACCESS AND NOTHING HOISTS IT — not VL, which has\n// no LICM, and not binaryen at `--closed-world -O3 --gufa -O3`, which keeps both\n// compares even when the loop guard four instructions above them is the\n// byte-identical comparison against the same constant. That is read off the\n// disassembly, not inferred from a stopwatch, and it is pinned as a shape by\n// `tests/vl_buffer_view_bounds_shape_test.ts`. P1.4 asks that the policy be stated,\n// not that it be eliminated; `docs/internals/buffer-design.md` §M is the\n// statement, with the price and the disassembly.\n//\n// The price is not what it looks like. On a loop holding ONE view the check\n// measures FREE at `-O3` (the compares are perfectly predicted and fill spare\n// issue slots); what costs is the per-access re-read of this struct's own `base`\n// and `length`, which binaryen hoists out of the loop only when GUFA can fold\n// them to constants — i.e. only when the program has one live view of the shape.\n// A two-view loop pays 7 field loads per element and runs 3.7x the hoisted\n// spelling. So the recipe for a kernel that has proved its own bounds is to take\n// the base and the count ONCE (`byteAddrF32(v, 0)`, `v.length`) and run the bare\n// intrinsics inside — measured identical to a hand-written raw kernel at EVERY\n// rung, no flag needed. `Buf`'s `loadF32`/`storeF32` are also still there, still\n// unfenced, and still take a byte offset.\n\n// The largest element count whose byte size fits in a positive i32, per width.\n// `count << 2` at 2^29 is already negative, so the count must be rejected BEFORE\n// the shift rather than after it.\nconst MAX_COUNT_4 = 536870911\n\n// A view of 4-byte floats. `base` is the byte address of element 0; `length` is\n// the element count. `new` is what keeps this distinct from `I32View`, which has\n// the identical shape — see this section's header.\nexport type F32View = new { base: i32, length: i32 }\n\n// A view of 4-byte signed integers.\nexport type I32View = new { base: i32, length: i32 }\n\n// Shared construction check for a 4-byte-element view over `self`: `off` is a\n// BYTE offset into the `Buf` and `count` is an ELEMENT count. Traps unless the\n// whole range `[off, off + count*4)` lies inside the `Buf`.\n//\n// This is the ALLOCATION-TIME check §J3 puts in std's hands, taken once per view\n// rather than once per access. It is what makes the per-access check able to be\n// just `0 <= i < length`: if the extent was validated when the view was made,\n// an in-range index cannot leave the `Buf`.\n//\n// A view may be EMPTY (`count == 0`), which is in-range for every offset up to\n// `length` and satisfies no index at all — the natural base case for a loop over\n// a column that happens to have no rows.\nfunction view4Base(self: Buf, off: i32, count: i32): i32 {\n  if off < 0 { __trap__() }\n  if count < 0 { __trap__() }\n  if count > MAX_COUNT_4 { __trap__() }\n  const bytes = count << 2\n  const end = off + bytes\n  if end < off { __trap__() }\n  if end > self.length { __trap__() }\n  return self.base + off\n}\n\n// `buf.f32view(off, count)` — `count` f32 elements starting at byte `off`.\nexport function f32view(self: Buf, off: i32, count: i32): F32View {\n  const b = view4Base(self, off, count)\n  return { base: b, length: count }\n}\n\n// `buf.i32view(off, count)` — `count` i32 elements starting at byte `off`.\nexport function i32view(self: Buf, off: i32, count: i32): I32View {\n  const b = view4Base(self, off, count)\n  return { base: b, length: count }\n}\n\n// Element `i` of an f32 view. Traps on an index outside `[0, length)`.\nexport function getF32(self: F32View, i: i32): f32 {\n  if i < 0 { __trap__() }\n  if i >= self.length { __trap__() }\n  return __load_f32__(self.base + (i << 2))\n}\n\n// Write element `i` of an f32 view. Traps on an index outside `[0, length)`.\nexport function setF32(self: F32View, i: i32, v: f32) {\n  if i < 0 { __trap__() }\n  if i >= self.length { __trap__() }\n  __store_f32__(self.base + (i << 2), v)\n}\n\n// Element `i` of an i32 view. Traps on an index outside `[0, length)`.\nexport function getI32(self: I32View, i: i32): i32 {\n  if i < 0 { __trap__() }\n  if i >= self.length { __trap__() }\n  return __load_i32__(self.base + (i << 2))\n}\n\n// Write element `i` of an i32 view. Traps on an index outside `[0, length)`.\nexport function setI32(self: I32View, i: i32, v: i32) {\n  if i < 0 { __trap__() }\n  if i >= self.length { __trap__() }\n  __store_i32__(self.base + (i << 2), v)\n}\n\n// ── the bracket (webcraft P1.1's spelling) ───────────────────────────────────\n// `x[i]` / `x[i] = v` over a view, as free INDEX-OPERATOR functions (B14). Each\n// is a one-line forward to the accessor above: same bounds check, same single\n// load/store, so the bracket is SPELLING, not a second access path, and the two\n// spellings mix freely in one loop.\n//\n// THE FORWARD IS A REAL FRAME AT THE UNOPTIMIZED RUNG. `x[i]` emits a call to\n// THIS function, which then calls `getF32` — two calls per access where\n// `x.getF32(i)` emits one. The modules are the same SIZE (one call index swapped\n// for another) but not the same bytes, and unoptimized the extra frame is\n// measurable. Both `-O` and `-O3` inline the forward away and the two spellings\n// converge, so this is a `vl build`-with-no-flags effect only; §M2 has the\n// number.\n//\n// Two `\"[]\"` declarations coexist because an index operator dispatches on its\n// `self` parameter's TYPE and the two views are distinct nominal brands — the\n// only thing that tells them apart, since their structures are identical.\n\nexport function \"[]\"(self: F32View, i: i32): f32 { return getF32(self, i) }\n\nexport function \"[]=\"(self: F32View, i: i32, v: f32) { setF32(self, i, v) }\n\nexport function \"[]\"(self: I32View, i: i32): i32 { return getI32(self, i) }\n\nexport function \"[]=\"(self: I32View, i: i32, v: i32) { setI32(self, i, v) }\n\n// The byte offset of element `i` RELATIVE TO the `Buf` the view was cut from is\n// not recoverable from the view alone (a view knows an absolute address, not its\n// parent). These two return the ABSOLUTE byte address of element `i`, which is\n// what a caller mixing view access with the bare intrinsics or with a host-side\n// typed array needs. No bounds check: this computes an address, it does not\n// dereference one, and `byteAddrF32(v, v.length)` — the one-past-the-end address\n// — is the useful answer for a range, not an error.\nexport function byteAddrF32(self: F32View, i: i32): i32 {\n  return self.base + (i << 2)\n}\n\nexport function byteAddrI32(self: I32View, i: i32): i32 {\n  return self.base + (i << 2)\n}\n",
  "std:fmt": "// `std:fmt` — pure-VL formatting helpers over the intrinsic floor\n// (docs/std-design.md D4 item 1). Imports nothing: strings are built with\n// `+`/`.slice` and rendered digit by digit. The exported helpers take a\n// `self` first parameter, so they read as UFCS methods on the receiver\n// (`n.toStr()`, `parts.join(sep)`). f64→string (shortest round-trip,\n// Ryu-class) is deliberately absent — `print` keeps covering floats.\n\n// Decimal digit d in 0..=9 as its character. Takes i64 so both integer\n// widths share one renderer (i64 cannot narrow to i32, so a string-index\n// lookup is not expressible for the wide path).\nfunction digitChar(d: i64) {\n  if d == 0 { return \"0\" }\n  if d == 1 { return \"1\" }\n  if d == 2 { return \"2\" }\n  if d == 3 { return \"3\" }\n  if d == 4 { return \"4\" }\n  if d == 5 { return \"5\" }\n  if d == 6 { return \"6\" }\n  if d == 7 { return \"7\" }\n  if d == 8 { return \"8\" }\n  \"9\"\n}\n\n// Decimal rendering of any i64, including i64 min. The accumulator works in\n// the NEGATIVE range (positive inputs are negated first) because the negative\n// range covers i64 min, whose magnitude overflows when negated; `%` on a\n// negative operand yields a digit in -9..=0, negated back per digit.\nfunction renderI64(n: i64) {\n  if n == 0 { return \"0\" }\n  const zero: i64 = 0\n  let m = n\n  if m > 0 { m = zero - m }\n  let out = \"\"\n  while m < 0 {\n    out = digitChar(zero - (m % 10)) + out\n    m = m / 10\n  }\n  if n < 0 { out = \"-\" + out }\n  out\n}\n\n// Decimal rendering of an integer via its receiver: `n.toStr()` over an i32\n// or i64 binding. One union receiver covers both widths (UFCS resolves by\n// `self`+arity; the value boxes in, `is`-narrows out); i32 widens losslessly\n// into the shared i64 renderer. The boolean arm renders true/false.\nexport function toStr(self: i32 | i64 | boolean) {\n  if self is boolean {\n    if self { return \"true\" }\n    return \"false\"\n  }\n  if self is i32 {\n    const wide: i64 = self\n    return renderI64(wide)\n  }\n  return renderI64(self)\n}\n\n// `self` concatenated n times; n <= 0 yields \"\".\nexport function repeat(self: string, n: i32) {\n  let out = \"\"\n  let i = 0\n  while i < n {\n    out = out + self\n    i = i + 1\n  }\n  out\n}\n\n// Pads `self` on the left with `fill` up to `width`. A multi-codepoint fill is\n// tiled and truncated so the result is exactly `width` long; returns `self`\n// unchanged when it is already wide enough or when fill is empty.\nexport function padLeft(self: string, width: i32, fill: string) {\n  if fill.length == 0 { return self }\n  const deficit = width - self.length\n  if deficit <= 0 { return self }\n  let pad = \"\"\n  let have = 0\n  while have < deficit {\n    pad = pad + fill\n    have = have + fill.length\n  }\n  return pad.slice(0, deficit) + self\n}\n\n// Elements of `self` concatenated with `sep` between consecutive elements.\nexport function join(self: string[], sep: string) {\n  let out = \"\"\n  let i = 0\n  while i < self.length {\n    if i > 0 { out = out + sep }\n    out = out + self[i]\n    i = i + 1\n  }\n  out\n}\n\n// Splits `self` into the substrings between each (non-overlapping, left-to-right)\n// occurrence of `sep`. An empty `sep` splits into individual characters; a `sep`\n// longer than the remaining text leaves the whole remainder as the final segment.\n// `\"a,b,c\".split(\",\")` → [\"a\", \"b\", \"c\"]; `\"\".split(\",\")` → [\"\"].\nexport function split(self: string, sep: string): string[] {\n  const out: string[] = []\n  if sep.length == 0 {\n    let i = 0\n    while i < self.length {\n      out.push(self.slice(i, i + 1))\n      i = i + 1\n    }\n    return out\n  }\n  let start = 0\n  let i = 0\n  while i <= self.length - sep.length {\n    if self.slice(i, i + sep.length) == sep {\n      out.push(self.slice(start, i))\n      i = i + sep.length\n      start = i\n    } else {\n      i = i + 1\n    }\n  }\n  out.push(self.slice(start, self.length))\n  return out\n}\n",
  "std:fs": "// `std:fs` — the filesystem, and VL's first FALLIBLE std module.\n//\n// Everything before this module was total: `std:fmt`, `std:array` and\n// `std:buffer` either answer or trap, because a bad index is a BUG. A missing\n// file is not a bug. It is a normal program state that the caller must be able\n// to handle, and `docs/error-handling-design.md` (owner-ruled 2026-07-26) says\n// how VL spells that: **errors are values, carried in the return type as a\n// union**. There is no `throw` here, no `try`, and nothing to catch. `__trap__`\n// appears in this file exactly zero times.\n//\n// THE THREE LAYERS, and which one each function uses:\n//   - `T | null`    — expected absence, no reason to carry. Not used for I/O\n//                     failure; used for \"the operation succeeded and has\n//                     nothing to report\" (`writeFile` returns `IoResult`, which\n//                     is `IoError | null`).\n//   - `T | IoError` — reasoned failure. Every read/list/stat surface.\n//   - trap          — a bug. Not reachable from anything in this module.\n//\n// `IoError = { code: i32, msg: string }` is the ruled I/O shape: `code` is the\n// WASI errno (`ENOENT` = 44, and the constants below name the ones worth\n// testing), `msg` is a human sentence naming the operation and the path. The\n// design doc's FLOOR shape is `{ msg: string }` and `IoError` is meant to\n// extend it; be warned that at this compiler head the extension does not\n// interoperate the way the doc implies — a value of shape `{code, msg}` does\n// NOT satisfy a `{msg}` parameter (structural width subtyping is a codegen\n// reject), and `x is Err` over a union whose arm is `IoError` is a hard type\n// error rather than a match. So a caller handles `IoError` by name, and a\n// function that wants to accept \"any error\" must spell the union.\n//\n// THE LADDER, and what it becomes. The `as` trio (`as` propagates, `as?`\n// coalesces to null, `as!` traps) is RULED but NOT BUILT — union-operand `as` is\n// still `` `as` supports numeric conversions only `` at this head. So callers\n// write the explicit check today:\n//\n//     function head(p: string): string | IoError {\n//       const src = readTextFile(p)\n//       if src is IoError { return src }      // re-raise, unchanged\n//       return src.slice(0, 80)               // `src` is a string here\n//     }\n//\n// and the same function, once the trio lands, is:\n//\n//     function head(p: string): string | IoError {\n//       return (readTextFile(p) as string).slice(0, 80)\n//     }\n//\n// This module is the consumer that boilerplate is supposed to be measured on.\n// Every `is IoError { return e }` below is one rung of it.\n//\n// NAMING, AND TWO DELIBERATE BREAKS WITH THE REST OF std. Both are required\n// reading before \"fixing\" them, per `docs/internals/std-api-review.md`.\n//\n// (1) NOT `self`-FIRST, so these are free functions and not UFCS methods. `self`\n// is not a style convention in VL — it is the UFCS SWITCH, matched by the\n// compiler on the literal parameter name, so a first parameter named `path` makes\n// method syntax unspellable. That is the point: the thing operated on here is the\n// FILE, not the string naming it, and `\"hello\".readTextFile()` would type-check\n// and be nonsense. Naming the parameter `path` removes that spelling by\n// construction rather than by convention.\n//\n// (2) NOUN-FIRST for the two questions — `pathKind` and `pathExists`, not `kind`\n// and `exists`. VL has no namespace import, so every export lands in the\n// importer's flat top-level scope and a bare `exists` collides with every other\n// existence check a program has. The prefix also marks the real split in this\n// module: `readFile`/`writeFile`/`listDir` OPERATE ON a file, while these two ASK\n// ABOUT a path. `pathKind` is deliberately not `stat`, because `stat` promises\n// POSIX's `stat` — size, mtime, mode — and this returns only file-or-directory;\n// a name that overpromises spends the good name before the feature arrives.\n//\n// WHAT CROSSES THE FLOOR. The intrinsics take and return `u8[]` — packed GC byte\n// arrays, no linear memory, no pointers, no capacities, no size negotiation.\n// Paths cross as UTF-8 bytes because that is what POSIX actually stores, and\n// file CONTENT crosses as bytes because a file is bytes: a PNG, a `.wasm` and a\n// zip are not text and must survive a round trip. Text is a DECODING on top,\n// which is why `readFile`/`readTextFile` are two functions with two types and\n// not one function with a flag. `std:utf8` owns the conversion and the\n// invalid-input policy in both directions.\n//\n// WHAT THIS MODULE DOES NOT DO. No path manipulation (join, normalize, extension\n// — that is a future `std:fs/path`, and until it exists `dir + \"/\" + name` is\n// the join). No open file handles, no seeking, no streaming, no partial reads:\n// every read here is whole-file, so a file larger than memory is not readable\n// through this surface. No metadata beyond file-or-directory — no size, no\n// mtime, no permissions, because the floor does not carry them. No mkdir, no\n// remove, no rename, no symlink inspection. Each of those is a floor intrinsic\n// that does not exist yet, and adding a std wrapper for a syscall VL cannot make\n// would be a name that fails at emit.\n//\n// CONCURRENCY AND TOCTOU. Nothing here is atomic against another process. A\n// path that `pathExists` reported yesterday can be gone by the next line, which is\n// why nothing in this module pre-checks on the caller's behalf: `readFile` does\n// not stat first to produce a prettier error, it just reads and reports what the\n// host said. A pre-check would cost a syscall and buy a race.\n\nimport { Utf8Error, decodeUtf8, decodeUtf8At, encodeUtf8 } from \"std:utf8\"\n\n// The blessed I/O error shape (`docs/error-handling-design.md` O3). `code` is\n// the WASI errno as a POSITIVE number — the floor reports `-errno` and this\n// module negates once, at the boundary, so a caller never sees a sign\n// convention.\nexport type IoError = { code: i32, msg: string }\n\n// The result of an operation that has NOTHING to report when it succeeds: a\n// reason, or `null` for \"it worked\". This is the `T | null` layer of the ruled\n// model doing exactly what it is for — a successful whole-file write has no\n// value to hand back, and inventing one (a byte count the floor never reported,\n// a boolean that is only ever `true`) would be fabricating information.\n//\n// Spelled as a NAMED alias rather than inline as `IoError | null` in each\n// signature, and that is a constraint rather than a preference: a struct that\n// appears both in an inline `S | null` and in some other union in the same\n// module fails at emit with `ref valtype with no interned shape`. The\n// declaration route interns the shape; the inline one does not.\nexport type IoResult = IoError | null\n\n// What a path names. A literal union rather than a struct or an i32: it is one\n// closed question with two answers today, `match` dispatches it exhaustively,\n// and a third answer (`\"symlink\"`) is a one-word edit that makes every existing\n// `match` fail loudly instead of silently falling through.\nexport type FileKind = \"file\" | \"dir\"\n\n// The errno numbers worth naming, in WASI preview1's numbering (which is what\n// the host reports and what `docs/error-handling-design.md` already uses when it\n// writes `{ code: 44, msg: \"no such file\" }`). These are the codes a program\n// actually branches on; the rest are rendered by number.\nexport const EACCES = 2\nexport const EILSEQ = 25\nexport const EINVAL = 28\nexport const EIO = 29\nexport const EISDIR = 31\nexport const ENOENT = 44\nexport const ENOSPC = 51\nexport const ENOTDIR = 54\nexport const EPERM = 63\n\n// The errno as a short name, or `\"errno N\"` for everything else. Deliberately\n// not a 76-arm table: these are the ones a caller can do something about, and a\n// number is a perfectly good rendering of a code nobody branches on.\nfunction errName(code: i32) {\n  if code == EACCES { return \"EACCES (permission denied)\" }\n  if code == EILSEQ { return \"EILSEQ (invalid byte sequence)\" }\n  if code == EINVAL { return \"EINVAL (invalid argument)\" }\n  if code == EIO { return \"EIO (i/o error)\" }\n  if code == EISDIR { return \"EISDIR (is a directory)\" }\n  if code == ENOENT { return \"ENOENT (no such file or directory)\" }\n  if code == ENOSPC { return \"ENOSPC (no space left on device)\" }\n  if code == ENOTDIR { return \"ENOTDIR (not a directory)\" }\n  if code == EPERM { return \"EPERM (operation not permitted)\" }\n  \"errno \" + toString(code)\n}\n\n// The one message shape, so every error out of this module reads the same and a\n// grep for one of them finds all of them. The operation is named because the\n// path alone does not say whether the read or the decode failed.\nfunction failed(op: string, path: string, code: i32) {\n  \"fs.\" + op + \" \" + path + \": \" + errName(code)\n}\n\n// The errno for a floor call that answered EMPTY.\n//\n// This is the one piece of GLOBAL STATE in the module's contract, and it is a\n// DEVIATION knowingly taken: `std-api-review.md` §2 flags ambient state, and the\n// rule there is that the header must name the constraint that forced it.\n//\n// The constraint was that neither in-band shape lowered — `u8[] | i32` was\n// check-clean invalid wasm and `u8[] | null` declined — so the reason had no\n// way to travel with the result and had to go out of band through\n// `__fs_errno__()`. Read it IMMEDIATELY after the failed call and never\n// otherwise.\n//\n// THAT CONSTRAINT HAS SINCE LIFTED (#1806 shipped `u8[]` into the union box's\n// kind vocabulary, so `u8[] | i32` now lowers and runs), and this wrapper is why\n// the swap is cheap: an in-band floor changes `emptyErrno` and its three callers\n// rather than every caller of the module. It is deliberately NOT taken in the\n// same change that introduces the module — swapping the floor means re-cutting\n// the intrinsics and both hosts, and the protocol below is correct as it stands.\n//\n// RETURNS 0 WHEN THE LAST CALL DID NOT FAIL, and that zero is load-bearing: the\n// floor reports failure by answering an EMPTY `u8[]`, which an empty FILE and an\n// empty DIRECTORY also produce. The errno is what tells those apart, so a zero\n// must reach `readOk` intact rather than being folded to `EIO` the way the\n// i32-returning `__fs_write__`/`__fs_stat__` paths fold theirs — there, a call\n// has already declared itself failed and a zero would be a contract violation;\n// here a zero is the ordinary answer.\n//\n// A negative errno is folded rather than propagated, so a floor that reports\n// `-ENOENT` and one that reports `ENOENT` are the same to every caller.\nfunction lastErrno(): i32 {\n  const e = __fs_errno__()\n  if e < 0 { return 0 - e }\n  e\n}\n\n// Whether an EMPTY result from a `u8[]`-returning intrinsic is a failure, and if\n// so which. Returns 0 for \"not a failure — the file or directory really is\n// empty\". One home for the empty-plus-errno protocol, so the three call sites\n// cannot drift, and so the swap to an in-band `u8[] | i32` floor (now expressible\n// — see #1806) is a change to this function rather than to every caller.\nfunction emptyErrno(): i32 { lastErrno() }\n\n// The message for an empty path, which every entry point rejects before it\n// reaches the floor. This is the ONLY policy this module applies ahead of the\n// syscall, and it earns its place twice: `\"\"` names nothing on any host (POSIX\n// `openat` answers ENOENT, other hosts vary), and answering identically\n// everywhere is worth one comparison.\n//\n// Only the MESSAGE is factored out, not the error value, and that is a\n// constraint rather than a preference: a struct produced by a CALL and flowing\n// into a union position does not lower — `return someHelper()` from a function\n// returning `T | IoError` fails at emit with `ref valtype with no interned\n// shape`. Every `IoError` in this file is therefore an object LITERAL written at\n// the site that returns it. Factoring them into a constructor is the obvious\n// tidy-up and it does not compile.\nfunction emptyPathMsg(op: string) { \"fs.\" + op + \": the path is empty\" }\n\n// `readFile(path)` — the whole file as bytes, or why not.\n//\n// BYTES, not text: this is the function that reads a PNG. Whole-file only —\n// there is no handle, no offset and no way to read part of one, so the result is\n// as large as the file and a file that does not fit in memory is not readable\n// here.\nexport function readFile(path: string): u8[] | IoError {\n  if path.length == 0 { return { code: EINVAL, msg: emptyPathMsg(\"readFile\") } }\n  const r = __fs_read__(encodeUtf8(path))\n  // EMPTY is the floor's failure signal AND a legitimate empty file, so the\n  // errno is the disambiguator — see `emptyErrno`.\n  if r.length == 0 {\n    const e = emptyErrno()\n    if e != 0 { return { code: e, msg: failed(\"readFile\", path, e) } }\n  }\n  r\n}\n\n// `readTextFile(path)` — the whole file, decoded as UTF-8.\n//\n// Two failures, one type: the read can fail (any errno the host reports) and the\n// DECODE can fail (`EILSEQ`, with the byte offset in the message). The second is\n// the honest answer to \"this file is not text\" — see `std:utf8` for why the\n// strict decode is the default and `decodeUtf8Lossy` is the opt-out. A caller\n// who wants the lossy behaviour reads bytes and decodes them itself; that is two\n// lines and it is not this function's decision to make.\nexport function readTextFile(path: string): string | IoError {\n  // Guarded here as well as in `readFile`, so the message names the function the\n  // caller actually called. Every OTHER error below is forwarded verbatim from\n  // the call that produced it, and keeps that call's operation name — which is\n  // where the failure really happened, and is more useful than a re-wrap.\n  if path.length == 0 {\n    return { code: EINVAL, msg: emptyPathMsg(\"readTextFile\") }\n  }\n  const bytes = readFile(path)\n  if bytes is IoError { return bytes }\n  const text = decodeUtf8(bytes)\n  if text is Utf8Error {\n    return { code: EILSEQ, msg: \"fs.readTextFile \" + path + \": \" + text.msg }\n  }\n  text\n}\n\n// `writeFile(path, data)` — replace the file's contents with `data`.\n//\n// Returns `IoResult` — `null` IS the success case, because a successful write\n// has nothing to report; no partial-write count exists at this floor, so\n// returning one would be a fabrication. The call site reads\n// `if e != null { … }`.\n//\n// Whether the file is created, truncated or replaced atomically is the HOST's\n// policy, not this module's, and it is documented where the intrinsic is.\nexport function writeFile(path: string, data: u8[]): IoResult {\n  if path.length == 0 {\n    return { code: EINVAL, msg: emptyPathMsg(\"writeFile\") }\n  }\n  const rc = __fs_write__(encodeUtf8(path), data)\n  if rc == 0 { return null }\n  // Negative is `-errno`. A POSITIVE non-zero is a floor protocol violation —\n  // reported as EIO rather than trapped, because a std module has no business\n  // killing the instance over a host that answered out of contract.\n  let code = EIO\n  if rc < 0 { code = 0 - rc }\n  { code: code, msg: failed(\"writeFile\", path, code) }\n}\n\n// `writeTextFile(path, text)` — the same, encoding `text` as UTF-8 first.\n// Encoding cannot fail (`std:utf8`'s header), so this adds no failure mode.\nexport function writeTextFile(path: string, text: string): IoResult {\n  if path.length == 0 {\n    return { code: EINVAL, msg: emptyPathMsg(\"writeTextFile\") }\n  }\n  writeFile(path, encodeUtf8(text))\n}\n\n// `listDir(path)` — the entries of a directory, as NAMES.\n//\n// Names, not paths: that is what the syscall reports, it is what you print, and\n// re-attaching the directory is one `+` (`dir + \"/\" + name`) which the caller\n// can skip entirely when it is about to `chdir`-relative or match on the name.\n// Returning joined paths would be a lossy convenience — you cannot recover the\n// name from a path without a path parser, and `std:fs/path` does not exist yet.\n// `\".\"` and `\"..\"` are NOT included (the host filters them); the order is the\n// host's and is not sorted.\n//\n// A single entry that is not valid UTF-8 fails the WHOLE call with `EILSEQ`.\n// That is deliberate: the alternative is silently dropping a file that exists,\n// which turns a listing into a wrong answer instead of a loud one. The message\n// carries the byte offset within the block so the entry is identifiable.\nexport function listDir(path: string): string[] | IoError {\n  if path.length == 0 { return { code: EINVAL, msg: emptyPathMsg(\"listDir\") } }\n  const block = __fs_list__(encodeUtf8(path))\n  // An EMPTY block is a failure or an empty directory; the errno separates them.\n  if block.length == 0 {\n    const e = emptyErrno()\n    if e != 0 { return { code: e, msg: failed(\"listDir\", path, e) } }\n  }\n  const out: string[] = []\n  let start = 0\n  let i = 0\n  // `i` runs one PAST the end so the final entry — which has no separator after\n  // it — is emitted by the same block as every other. `atSep` is computed in two\n  // steps rather than folded into one `||`, so nothing indexes the array at\n  // `length`.\n  while i <= block.length {\n    let atSep = i == block.length\n    if !atSep { atSep = block[i] == 0x00 }\n    if atSep {\n      // Empty runs are skipped rather than yielded, which makes this agnostic\n      // to whether the host treats 0x00 as a SEPARATOR or a TERMINATOR — a\n      // filename is never empty, so a zero-length run carries no information.\n      if i > start {\n        const name = decodeUtf8At(block, start, i - start)\n        if name is Utf8Error {\n          return {\n            code: EILSEQ,\n            msg: \"fs.listDir \" +\n              path +\n              \": entry at byte \" +\n              toString(start + name.at) +\n              \" is not UTF-8\",\n          }\n        }\n        out.push(name)\n      }\n      start = i + 1\n    }\n    i = i + 1\n  }\n  out\n}\n\n// `pathKind(path)` — what `path` names, or why the question could not be answered.\n//\n// A missing path is an ERROR here (`ENOENT`), not a third `FileKind`: \"there is\n// nothing here\" is not a kind of thing, and folding it into the success arm is\n// what makes callers forget that `EACCES` is also possible. `pathExists` is the\n// function that turns ENOENT into a boolean, and it is separate precisely so\n// that decision is made once and visibly.\nexport function pathKind(path: string): FileKind | IoError {\n  if path.length == 0 { return { code: EINVAL, msg: emptyPathMsg(\"pathKind\") } }\n  const k = __fs_stat__(encodeUtf8(path))\n  if k == 0 { return \"file\" }\n  if k == 1 { return \"dir\" }\n  let code = EIO\n  if k < 0 { code = 0 - k }\n  { code: code, msg: failed(\"pathKind\", path, code) }\n}\n\n// `pathExists(path)` — whether `path` names anything, or why that is unanswerable.\n//\n// `boolean | IoError`, NOT `boolean`, and this is the whole reason the function\n// is worth writing down. \"Does not exist\" and \"you are not allowed to look\" are\n// different facts, and a `boolean` return has to lie about one of them.\n// `Path::exists()` in Rust and `os.path.exists` in Python both answer `false`\n// for a permission error, and both ship a documented footgun where a program\n// creates a file it was told was absent, or reports a config missing when the\n// truth is the directory is unreadable.\n//\n// So exactly two errnos become `false`, and both mean \"nothing is there\":\n//   - ENOENT  — no such file or directory;\n//   - ENOTDIR — a component of the path is not a directory, so nothing can be\n//               at the end of it.\n// Everything else — EACCES, EPERM, EIO, a loop, a name too long — propagates\n// with its reason intact.\nexport function pathExists(path: string): boolean | IoError {\n  const k = pathKind(path)\n  if k is IoError {\n    if k.code == ENOENT { return false }\n    if k.code == ENOTDIR { return false }\n    return k\n  }\n  true\n}\n",
  "std:seed": "// `std:seed` — a trivial module whose only job is to prove the `std:`\n// resolution plumbing end to end (both resolvers, the Rust host's std-dir\n// mapping, the CLI's fsRead wrap, the LSP's embedded map). Real std content\n// (`std:fmt`, `std:test`, collections) lands in later slices\n// (docs/std-design.md D4); this file can be retired once any of them exists.\nexport function stdSmoke() { return 7 }\n",
  "std:test": "// `std:test` v1 — the in-language testing surface (docs/std-design.md D5), in two\n// halves over the intrinsic floor:\n//\n//   1. REGISTRATION — jest-shaped `describe`/`it`/`beforeEach`/`afterEach`. Calling\n//      them at a file's top level REGISTERS into the module-level parallel arrays\n//      below and does nothing else; the wasm start function runs that top level at\n//      instantiation, after which the registry is complete (two-phase collection —\n//      `describe` bodies are REGISTRATION-ONLY, the Deno-steps lesson).\n//   2. ASSERTION — `expect(...)` matchers, read jest-shaped through STRUCT-RECEIVER\n//      UFCS: `expect(x).toEqual(y)` builds an `Expectation` and `.toEqual` is a free\n//      `self`-function resolved by self+arity. A failed assertion records its\n//      rendered message and calls `__trap__()` (jest's \"a test stops at its first\n//      failed expectation\"); a passing one is a no-op.\n//\n// The `vlt*` exports at the bottom are the RUNNER PROTOCOL — the host reads the\n// registry through them and drives one test per call, which is what buys per-test\n// trap isolation, output attribution and filtering\n// (docs/internals/test-runner-design.md). `vl test` APPENDS\n// `export { … } from \"std:test\"` to each `*.test.vl` it compiles, so a test file\n// never writes the protocol line itself.\n//\n// Under bare `vl run` a green file exits 0 and a red one aborts, with no runner.\n//\n// `expect` takes a VALUE UNION over the comparable atoms, so ONE entry point covers\n// every value kind — the value boxes into the union and `is`-narrows back out.\n// (`toBe` referential identity is reserved for the future `===`, ROADMAP A15;\n// `toThrow`/`toBeNull` wait on the error model / `null` in the value union —\n// std-design OD6.)\n//\n// ── ONE VL RULE GOVERNS THIS FILE'S SHAPE ──────────────────────────────────────\n// A function's result type is its TAIL statement's, and a test BODY is typed\n// `() => void`, so every function a body can end with must itself be void. The\n// statements that yield NOTHING are few — a call to a void function, a `while`, a\n// `const` declaration, an `if` whose branches are void — while an assignment and a\n// `.push` both yield a value. That is why the registration functions close with\n// `vltDone()` and the matchers close with a call rather than an `if`: without it,\n// `it(\"x\", () => { expect(1).toEqual(1) })` fails to typecheck with\n// `expected () -> void, got () -> i32`.\n\n// ── the registry ────────────────────────────────────────────────────────────────\n// PARALLEL ARRAYS, the compiler driver's own idiom (`modKeys`/`modPending`/…): one\n// entry per registered test, index `i` is the protocol's test id.\nconst vltNames: string[] = []        // the test's full path (scope > … > name)\nconst vltBodies: (() => void)[] = [] // its body\nconst vltSkips: i32[] = []           // 1 = registered by `itSkip`\nconst vltScopes: string[] = []       // the enclosing `describe` path (hook matching)\n\n// The `describe` path currently being registered into (\"\" at file scope). Saved and\n// restored around each `describe` body, so nesting composes.\nlet vltScope = \"\"\n\n// Hooks, also parallel: each records the `describe` scope it was declared in, and\n// runs around every test at or beneath that scope.\nconst vltBeforeScopes: string[] = []\nconst vltBeforeFns: (() => void)[] = []\nconst vltAfterScopes: string[] = []\nconst vltAfterFns: (() => void)[] = []\n\n// The rendered message of the assertion that just aborted the running test. The\n// runner reads it AFTER catching the trap (`vltFailLen`/`vltFailAt`) — a trap\n// unwinds the call but leaves the instance readable — so a failure reports its\n// message structurally instead of being scraped out of print output.\nlet vltFailMsg = \"\"\n\n// A VOID no-op — the tail that makes a function whose real work ends in an\n// assignment or a `.push` still type as `() -> void`. See the rule above.\nfunction vltDone() {}\n\n// The same no-op, EXPORTED, for closing a test body whose last real statement\n// yields a value:\n//\n//   beforeEach(() => { hits = hits + 1  done() })\n//\n// Without it that body types as `() => i32` and the registration call rejects it\n// with `expected () -> void, got () -> i32`. A body ending in an `expect(…)`\n// matcher — the overwhelming majority — needs nothing. (The language-level fix is\n// void-return covariance on function values, which is not free: the array's\n// element type IS the interned `$fnsig`, so it needs a real coercion, not a\n// relaxed check. Filed in docs/internals/vl-test-design.md §Known gaps.)\nexport function done() {}\n\n// ── registration ────────────────────────────────────────────────────────────────\n\n// Group the tests registered by `body` under `name`. REGISTRATION ONLY: the body\n// runs at collect time, so it must do nothing but declare tests and hooks (any\n// real work would run once, at the wrong time, for every test in the file).\nexport function describe(name: string, body: () => void) {\n  const saved = vltScope\n  if vltScope.length > 0 {\n    vltScope = vltScope + \" > \" + name\n  } else {\n    vltScope = name\n  }\n  body()\n  vltScope = saved\n  vltDone()\n}\n\n// The shared registration path. `path` is the scope-qualified name the report and\n// the `-t` filter both match against.\nfunction vltRegister(name: string, body: () => void, skip: i32) {\n  let path = name\n  if vltScope.length > 0 { path = vltScope + \" > \" + name }\n  vltNames.push(path)\n  vltBodies.push(body)\n  vltSkips.push(skip)\n  vltScopes.push(vltScope)\n  vltDone()\n}\n\n// Register one test.\nexport function it(name: string, body: () => void) {\n  vltRegister(name, body, 0)\n}\n\n// Register one test as SKIPPED — it is collected, reported, and never run (the\n// `#[ignore]`/`@Disabled` analog; `.skip` is not spellable because VL has no\n// property access on a function value).\nexport function itSkip(name: string, body: () => void) {\n  vltRegister(name, body, 1)\n}\n\n// Run `body` before each test at or beneath the enclosing `describe` scope.\nexport function beforeEach(body: () => void) {\n  vltBeforeScopes.push(vltScope)\n  vltBeforeFns.push(body)\n  vltDone()\n}\n\n// Run `body` after each test at or beneath the enclosing `describe` scope.\n// Registration order is preserved; `vltRun` fires them in REVERSE, so hooks nest\n// like scopes do (outermost `before` first, outermost `after` last).\nexport function afterEach(body: () => void) {\n  vltAfterScopes.push(vltScope)\n  vltAfterFns.push(body)\n  vltDone()\n}\n\n// Does a hook declared at scope `hook` apply to a test whose scope is `test`? The\n// file scope (\"\") applies to everything; otherwise `test` must be `hook` itself or\n// one of its descendants — a PATH-SEGMENT prefix test, so a `describe(\"list\")`\n// hook does not leak into `describe(\"listener\")`.\nfunction vltInScope(hook: string, test: string) {\n  if hook.length == 0 { return 1 }\n  if hook == test { return 1 }\n  const sep = hook + \" > \"\n  if test.length >= sep.length {\n    const head = test.slice(0, sep.length)\n    if head == sep { return 1 }\n  }\n  0\n}\n\n// ── assertion ───────────────────────────────────────────────────────────────────\n\ntype Expectation = {\n  actual: i32 | i64 | f64 | boolean | string,\n  negated: boolean\n}\n\n// `expect(value)` — the receiver for the matchers.\nexport function expect(value: i32 | i64 | f64 | boolean | string): Expectation {\n  return { actual: value, negated: false }\n}\n\n// Inverts the pass/fail sense: `expect(5).not().toEqual(6)` passes. Returns a\n// fresh `Expectation` (the receiver is a value; no aliasing).\nexport function not(self: Expectation): Expectation {\n  return { actual: self.actual, negated: !self.negated }\n}\n\n// Record the rendered message and abort the test. The runner catches the trap,\n// reads `vltFailMsg` back, and continues with the next test. Void: its tail is\n// `__trap__()`, which yields nothing (and never returns).\nfunction vltAbort(msg: string) {\n  vltFailMsg = msg\n  __trap__()\n}\n\n// One decimal digit as its character. i64 so both integer widths share the\n// renderer (i64 cannot narrow to i32, so a string-index lookup is not expressible\n// for the wide path). Mirrors `std:fmt`'s technique rather than importing it: no\n// std module imports another today, and the assertion surface is not the place to\n// make std's own module graph load-bearing for the first time.\nfunction vltDigit(d: i64) {\n  if d == 0 { return \"0\" }\n  if d == 1 { return \"1\" }\n  if d == 2 { return \"2\" }\n  if d == 3 { return \"3\" }\n  if d == 4 { return \"4\" }\n  if d == 5 { return \"5\" }\n  if d == 6 { return \"6\" }\n  if d == 7 { return \"7\" }\n  if d == 8 { return \"8\" }\n  \"9\"\n}\n\n// Decimal rendering of any i64, i64 min included: the accumulator works in the\n// NEGATIVE range (positive inputs are negated first) because the negative range\n// covers i64 min, whose magnitude overflows when negated.\nfunction vltI64Str(v: i64) {\n  if v == 0 { return \"0\" }\n  let n = v\n  let neg = false\n  if v > 0 { n = 0 - v } else { neg = true }\n  let out = \"\"\n  while n < 0 {\n    const d = 0 - (n % 10)\n    out = vltDigit(d) + out\n    n = n / 10\n  }\n  if neg { return \"-\" + out }\n  out\n}\n\n// How a value reads in a failure message. Strings are quoted so `\"4\"` and `4` are\n// distinguishable at a glance (they are unequal — a cross-variant `==` is false).\n// f64 has no pure-VL renderer yet (std-design D4 defers shortest-round-trip\n// f64→string), so it renders as its type and `vltEcho` streams the real value\n// through `print` instead — the runner captures that as the test's output.\nfunction vltShow(v: i32 | i64 | f64 | boolean | string): string {\n  if v is string { return \"\\\"\" + v + \"\\\"\" }\n  if v is boolean {\n    if v { return \"true\" }\n    return \"false\"\n  }\n  if v is i32 {\n    const wide = v as i64\n    return vltI64Str(wide)\n  }\n  if v is i64 { return vltI64Str(v) }\n  \"<f64>\"\n}\n\n// The f64 half of the rendering story: print the value so the captured output\n// carries the digits the message cannot. A no-op for every other variant.\nfunction vltEcho(v: i32 | i64 | f64 | boolean | string) {\n  if v is f64 { print(v) }\n}\n\n// Render + abort. Reached ONLY on failure, which is why the matchers hand over\n// their operands instead of a pre-built string: a passing assertion must not pay\n// for a message nobody reads (a table-driven suite runs millions of them).\n// `kind`: 0 = toEqual, 1 = toBeTrue, 2 = toBeFalse.\nfunction vltReport(\n  self: Expectation,\n  kind: i32,\n  expected: i32 | i64 | f64 | boolean | string,\n) {\n  const a = self.actual\n  let tail = \"be true\"\n  if kind == 0 {\n    vltEcho(a)\n    vltEcho(expected)\n    tail = \"equal \" + vltShow(expected)\n  }\n  if kind == 2 { tail = \"be false\" }\n  let sense = \"to \"\n  if self.negated { sense = \"not to \" }\n  vltAbort(\"expected \" + vltShow(a) + \" \" + sense + tail)\n}\n\n// Aborts unless `ok` agrees with the current sense (`negated`). Factored so every\n// matcher shares one pass/fail decision — and so each matcher's TAIL is this void\n// call, which is what types a test body as `() => void`.\nfunction vltAdjudicate(\n  self: Expectation,\n  ok: boolean,\n  kind: i32,\n  expected: i32 | i64 | f64 | boolean | string,\n) {\n  if self.negated {\n    if ok { vltReport(self, kind, expected) }\n  } else {\n    if !ok { vltReport(self, kind, expected) }\n  }\n}\n\n// `.toEqual` — structural equality, jest semantics. The union `==` compares the two\n// values' live variants (a cross-variant pair, `expect(4).toEqual(\"4\")`, is\n// unequal). `self.actual` binds to a local first: union `==` requires binding\n// operands, not a raw field read.\nexport function toEqual(\n  self: Expectation,\n  expected: i32 | i64 | f64 | boolean | string,\n) {\n  const a = self.actual\n  const ok = a == expected\n  vltAdjudicate(self, ok, 0, expected)\n}\n\n// `.toBeTrue` — the receiver holds boolean `true`. A non-boolean receiver is\n// never true (the `is` arm simply does not fire).\nexport function toBeTrue(self: Expectation) {\n  const a = self.actual\n  let ok = false\n  if a is boolean { ok = a }\n  vltAdjudicate(self, ok, 1, a)\n}\n\n// `.toBeFalse` — the receiver holds boolean `false`.\nexport function toBeFalse(self: Expectation) {\n  const a = self.actual\n  let ok = false\n  if a is boolean { ok = !a }\n  vltAdjudicate(self, ok, 2, a)\n}\n\n// Fail the running test outright with `msg` — the escape hatch for a condition no\n// matcher expresses (`if !reachedTheBranch { fail(\"unreachable\") }`).\nexport function fail(msg: string) { vltAbort(msg) }\n\n// ── the runner protocol ─────────────────────────────────────────────────────────\n// Read by the host after instantiation (the start function has just registered\n// everything). Strings cross one code point at a time — the driver's\n// `modPendingCount`/`modPendingLen`/`modPendingAt` idiom, which the host already\n// speaks. `vl test` re-exports these into each `*.test.vl` module it compiles.\n\n// How many tests this file registered.\nexport function vltCount(): i32 { vltNames.length }\n\n// Code-point length of test `i`'s scope-qualified name.\nexport function vltNameLen(i: i32): i32 { vltNames[i].length }\n\n// Code point `j` of test `i`'s name.\nexport function vltNameAt(i: i32, j: i32): i32 { vltNames[i][j] }\n\n// 1 when test `i` was registered by `itSkip`.\nexport function vltSkipped(i: i32): i32 { vltSkips[i] }\n\n// Run test `i` with its hook chain. 0 = passed, 1 = skipped; a FAILURE does not\n// return — the assertion traps, and the host reads `vltFail*` for the message.\nexport function vltRun(i: i32): i32 {\n  vltFailMsg = \"\"\n  if vltSkips[i] != 0 { return 1 }\n  const scope = vltScopes[i]\n  let h = 0\n  while h < vltBeforeScopes.length {\n    if vltInScope(vltBeforeScopes[h], scope) != 0 {\n      const before = vltBeforeFns[h]\n      before()\n    }\n    h = h + 1\n  }\n  const body = vltBodies[i]\n  body()\n  let a = vltAfterScopes.length - 1\n  while a >= 0 {\n    if vltInScope(vltAfterScopes[a], scope) != 0 {\n      const after = vltAfterFns[a]\n      after()\n    }\n    a = a - 1\n  }\n  0\n}\n\n// Code-point length of the last failure message (0 = the trap carried none, e.g. a\n// raw `__trap__()` or an out-of-bounds index rather than a failed expectation).\nexport function vltFailLen(): i32 { vltFailMsg.length }\n\n// Code point `j` of the last failure message.\nexport function vltFailAt(j: i32): i32 { vltFailMsg[j] }\n",
  "std:utf8": "// `std:utf8` — the boundary between VL's strings and the byte world.\n//\n// WHY THIS MODULE EXISTS. A VL `string` is a sequence of Unicode CODE POINTS:\n// `s.length` counts code points, `s[i]` and `s.charCodeAt(i)` yield the whole\n// code point, and `fromCodePoints` builds one back from an `i32[]`. A `u8[]` is\n// a sequence of BYTES — `u8` is a STORAGE type, so an element is one byte that\n// reads out widened to `i32` (0..255) and truncates on write, the same split\n// wasm itself makes between i8 as an array element and i8 as a value, which\n// does not exist. Files, paths, argv, stdin and every other boundary VL will\n// grow are bytes; UTF-8 is the conversion between the two worlds, and it has to\n// be written exactly once. It lives in its own module rather than privately\n// inside `std:fs` because `std:fs` is merely the FIRST consumer, and a private\n// copy is how a program ends up with two decoders holding two different\n// opinions about invalid input.\n//\n// THE INVALID-INPUT RULING, both directions, because it is the whole design:\n//\n//   ENCODE IS TOTAL. `encodeUtf8` cannot fail. A VL string is an i32 sequence\n//   and nothing stops it holding -1, 0x110000 or a lone surrogate\n//   (`fromCodePoints` accepts any `i32[]`) — none of which is a Unicode scalar\n//   value, and none of which has a UTF-8 encoding. Each such element is encoded\n//   as U+FFFD. The alternative — a fallible encoder — would infect the signature\n//   of every caller that merely wants to name a FILE, for an input no correct\n//   program produces, and it would still have to emit *some* bytes. Substitution\n//   buys the invariant that matters: what leaves here is always well-formed\n//   UTF-8, so the host that receives it (a Rust `str`, a POSIX path) never\n//   rejects it.\n//\n//   DECODE IS FALLIBLE, AND STRICT BY DEFAULT. `decodeUtf8` returns\n//   `string | Utf8Error` and rejects every ill-formed sequence: bad lead byte,\n//   bad continuation, overlong form, surrogate, beyond U+10FFFF, truncated\n//   tail. This is Rust's `from_utf8`, not `from_utf8_lossy`, and the reason the\n//   strict one is the DEFAULT is that a decode failure is information: those\n//   bytes are not text, and the program about to treat them as text is about to\n//   be wrong. Silently substituting U+FFFD would turn \"this is a PNG\" into a\n//   string of question marks that compares unequal to everything and explains\n//   nothing. `decodeUtf8Lossy` is the deliberate opt-out for a caller who would\n//   rather render mojibake than stop — a log tailer, an editor opening whatever\n//   it was handed — and substitutes one U+FFFD per maximal ill-formed subpart,\n//   which is the WHATWG rule.\n//\n// WHAT THIS MODULE DOES NOT DO. No UTF-16, no other encodings, no BOM handling\n// (a leading U+FEFF decodes to U+FEFF and stays in the string — stripping it is\n// a policy for whoever knows the format), no normalization, no grapheme or\n// display-width analysis. Those are not \"later here\"; they are a different\n// module.\n\n// A decode failure, carrying the position AND the offending byte.\n//\n// `at` is the byte offset of the failure WITHIN THE DECODED RANGE — relative to\n// the `off` that was passed in, never an absolute index — so it stays meaningful\n// to a caller decoding a slice out of a larger array. `byte` is the lead byte\n// that could not be decoded, which was previously only stringified into `msg`\n// and so could not be inspected without parsing prose.\n//\n// `byte` IS ALSO WHAT KEEPS THIS TYPE DISTINCT. `error-handling-design.md` §90\n// blesses `ParseError = { at: i32, msg: string }`, and VL aliases are\n// STRUCTURAL — so the two-field shape would make `Utf8Error` and `ParseError`\n// literally one type, and a union naming both (`Config | ParseError | Utf8Error`,\n// which that document's own worked example is one step away from) would fail at\n// emit with `union box atom test on a union with no recorded members`.\n// `ParseError` does not exist in code yet, so this module would have silently\n// taken its seat and the first parser VL grows would have collided.\nexport type Utf8Error = { at: i32, byte: i32, msg: string }\n\n// U+FFFD, substituted in both directions.\nconst REPLACEMENT = 0xFFFD\n\n// `cp` if it is a Unicode scalar value, U+FFFD otherwise. The three non-scalars\n// an i32 can hold: below the range, above it, and the surrogate block\n// D800..DFFF — which UTF-8 must never carry (a codec that accepts them is\n// CESU-8/WTF-8, not UTF-8).\nfunction scalar(cp: i32) {\n  if cp < 0 { return REPLACEMENT }\n  if cp > 0x10FFFF { return REPLACEMENT }\n  if cp >= 0xD800 && cp <= 0xDFFF { return REPLACEMENT }\n  cp\n}\n\n// How many bytes `cp` occupies once encoded — applying the SAME substitution the\n// encoder applies, which is what makes `utf8Length` an exact prediction of what\n// `encodeUtf8` produces rather than an estimate. One width function, so the\n// measurement and the encoder cannot drift.\nfunction utf8Width(cp: i32) {\n  const c = scalar(cp)\n  if c < 0x80 { return 1 }\n  if c < 0x800 { return 2 }\n  if c < 0x10000 { return 3 }\n  4\n}\n\n// `s.utf8Length()` — the exact length of `s.encodeUtf8()`, WITHOUT encoding it.\n// Distinct from `s.length`, which counts code points: the two agree for ASCII\n// and for nothing else. Exported because it is the only way to answer \"how big\n// will this be on the wire\" — a size check, a quota, a header field — short of\n// producing the bytes and throwing them away.\nexport function utf8Length(self: string) {\n  let n = 0\n  let i = 0\n  while i < self.length {\n    n = n + utf8Width(self.charCodeAt(i))\n    i = i + 1\n  }\n  n\n}\n\n// `s.encodeUtf8()` — `s` as UTF-8 bytes. Total: a non-scalar element encodes as\n// U+FFFD (this module's header).\nexport function encodeUtf8(self: string): u8[] {\n  const out: u8[] = []\n  let i = 0\n  while i < self.length {\n    const c = scalar(self.charCodeAt(i))\n    if c < 0x80 {\n      out.push(c)\n    } else if c < 0x800 {\n      out.push(0xC0 | (c >> 6))\n      out.push(0x80 | (c & 0x3F))\n    } else if c < 0x10000 {\n      out.push(0xE0 | (c >> 12))\n      out.push(0x80 | ((c >> 6) & 0x3F))\n      out.push(0x80 | (c & 0x3F))\n    } else {\n      out.push(0xF0 | (c >> 18))\n      out.push(0x80 | ((c >> 12) & 0x3F))\n      out.push(0x80 | ((c >> 6) & 0x3F))\n      out.push(0x80 | (c & 0x3F))\n    }\n    i = i + 1\n  }\n  out\n}\n\n// The one decode loop. The strict/lossy fork is a PARAMETER rather than two\n// copies so the two public spellings cannot disagree about what \"ill-formed\"\n// means — the bug that shows up as a validator and a consumer accepting\n// different byte strings.\n//\n// The validity table is the standard one, and every row of it rejects a sequence\n// a naive shift-and-or would happily decode:\n//   C0 C1        overlong two-byte forms of ASCII\n//   E0 80..9F    overlong three-byte forms\n//   ED A0..BF    the surrogate block\n//   F0 80..8F    overlong four-byte forms\n//   F4 90..BF    beyond U+10FFFF\n//   F5..FF       no such lead byte\n// Accepting any of them is the classic security bug: two byte strings decoding\n// to one string is how a path check that already ran gets walked past.\nfunction decodeCore(\n  self: u8[],\n  off: i32,\n  len: i32,\n  lossy: boolean,\n): string | Utf8Error {\n  const cps: i32[] = []\n  let i = 0\n  while i < len {\n    const b0 = self[off + i]\n    // The sequence length comes from the lead byte, together with the TIGHTENED\n    // bounds the FIRST continuation byte must satisfy (every later one is the\n    // plain 0x80..0xBF).\n    let size = 0\n    let cp = 0\n    let lo = 0x80\n    let hi = 0xBF\n    if b0 < 0x80 {\n      size = 1\n      cp = b0\n    } else if b0 >= 0xC2 && b0 <= 0xDF {\n      size = 2\n      cp = b0 & 0x1F\n    } else if b0 >= 0xE0 && b0 <= 0xEF {\n      size = 3\n      cp = b0 & 0x0F\n      if b0 == 0xE0 { lo = 0xA0 }\n      if b0 == 0xED { hi = 0x9F }\n    } else if b0 >= 0xF0 && b0 <= 0xF4 {\n      size = 4\n      cp = b0 & 0x07\n      if b0 == 0xF0 { lo = 0x90 }\n      if b0 == 0xF4 { hi = 0x8F }\n    }\n    // `good` counts the MAXIMAL VALID SUBPART — how far the sequence got before\n    // it went wrong, never less than 1. It is what the lossy path advances by,\n    // so a truncated 4-byte sequence at the end of the range yields ONE U+FFFD\n    // rather than one per leftover byte. That is the WHATWG rule, and it is also\n    // the only advance that cannot loop: `good >= 1` always.\n    let ok = size > 0\n    let good = 1\n    let k = 1\n    while ok && k < size {\n      if i + k >= len {\n        ok = false\n      } else {\n        const b = self[off + i + k]\n        let blo = 0x80\n        let bhi = 0xBF\n        if k == 1 {\n          blo = lo\n          bhi = hi\n        }\n        if b < blo || b > bhi {\n          ok = false\n        } else {\n          cp = (cp << 6) | (b & 0x3F)\n          good = good + 1\n        }\n      }\n      k = k + 1\n    }\n    if ok {\n      cps.push(cp)\n      i = i + size\n    } else if lossy {\n      cps.push(REPLACEMENT)\n      i = i + good\n    } else {\n      return {\n        at: i,\n        byte: b0,\n        msg: \"invalid UTF-8: byte \" + toString(b0) + \" at offset \" + toString(i),\n      }\n    }\n  }\n  fromCodePoints(cps)\n}\n\n// `b.decodeUtf8()` — the whole array as a string, or the position of the first\n// ill-formed sequence. STRICT; see the header for why strict is the default.\nexport function decodeUtf8(self: u8[]): string | Utf8Error {\n  decodeCore(self, 0, self.length, false)\n}\n\n// `b.decodeUtf8At(off, len)` — the same, over one range. The range form exists\n// because a consumer that splits a byte block into records (`std:fs`'s\n// directory listing, a line reader) must attribute a decode failure to the\n// RECORD, not to the block.\nexport function decodeUtf8At(\n  self: u8[],\n  off: i32,\n  len: i32,\n): string | Utf8Error {\n  decodeCore(self, off, len, false)\n}\n\n// `b.decodeUtf8Lossy()` — the whole array, with one U+FFFD per maximal\n// ill-formed subpart. Total: there is no input this rejects.\nexport function decodeUtf8Lossy(self: u8[]) {\n  const r = decodeCore(self, 0, self.length, true)\n  // Unreachable: the lossy path substitutes rather than returning the error arm.\n  // The narrowing is what makes the `string` return type provable, and the trap\n  // is what makes a future edit that breaks the invariant loud instead of\n  // silent — VL has no way to say \"this arm cannot happen\" in a type.\n  if r is Utf8Error {\n    __trap__(\"std:utf8: lossy decode reported an error\")\n    return \"\"\n  }\n  r\n}\n",
};
